```python
def is_composite(n):
    """Check if a number is composite."""
    if n < 4:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return True
    return False

def can_be_written_as_42a_plus_c(n):
    """Check if a number can be written as 42a + c where c is a composite number."""
    for a in range(1, n // 42 + 1):
        if (n - 42 * a) > 0 and is_composite(n - 42 * a):
            return True
    return False

# We'll start from a reasonably large number and go downwards
target = 10000  # Start from a reasonably large number
while True:
    if not can_be_written_as_42a_plus_c(target):
        break
    target -= 1

print(target)
