```python
import sympy as sp

# Function to check if a number can be expressed as 42a + c
def can_be_expressed(n):
    for a in range(1, n // 42 + 1):
        c = n - 42 * a
        if c > 0 and sp.isprime(c):
            return False
    return True

# Find the largest integer that cannot be expressed as 42a + c
def find_largest_non_expressible():
    for n in range(1000, 0, -1):
        if not can_be_expressed(n):
            return n

largest_non_expressible = find_largest_non_expressible()
print(largest_non_expressible)
```
