\begin{align*}
PH^2 &= PA^2 + PB^2 + PC^2 - 2PA \cdot PB \cos \angle APB - 2PA \cdot PC \cos \angle APC - 2PB \cdot PC \cos \angle BPC \\
&= PA^2 + PB^2 + PC^2 - 2PA \cdot PB \left(\frac{a^2 + b^2 - c^2}{2s}\right) - 2PA \cdot PC \left(\frac{a^2 + c^2 - b^2}{2s}\right) - 2PB \cdot PC \left(\frac{b^2 + c^2 - a^2}{2s}\right).
