   \[
   z + \frac{1}{z} = \left( x + yi \right) + \left( \frac{x}{4} - \frac{y}{4}i \right) = \left( x + \frac{x}{4} \right) + \left( y - \frac{y}{4} \right)i = \frac{5x}{4} + \frac{3y}{4}i.
   \]
